update public.content_variants set body = $json${"type":"multiple_choice","answer":"IDR 700,000","options":["IDR 350,000","IDR 700,000","IDR 3,500,000","IDR 7,000,000"],"question":"If the TLKM share price is IDR 3,500 per share, how much does it cost to buy 2 lots?","difficulty":"beginner","parameters":{},"explanation":"2 lots = 200 shares. 200 × IDR 3,500 = IDR 700,000."}$json$::jsonb where id = '63380433-e391-450d-8c88-ad96a740dee3';
update public.content_variants set body = $json${"type":"ordering","answer":["Set goals","Prepare an emergency fund","Pay off high-interest debt","Choose investment instruments according to your goals"],"options":["Set goals","Prepare an emergency fund","Pay off high-interest debt","Choose investment instruments according to your goals"],"question":"Sequence the steps to create a basic financial plan.","difficulty":"advanced","explanation":"Start with your goals, protect them with emergency funds, free yourself from high-interest debt, then invest."}$json$::jsonb where id = '639c01b7-9667-4624-8aad-4c3daf4b570f';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Decrease in the purchasing power of money for goods and services","options":["Increase in money supply","Decrease in the purchasing power of money for goods and services","Increase in the rupiah exchange rate","General reduction in prices of goods"],"question":"What is meant by inflation?","difficulty":"beginner","parameters":{},"explanation":"Inflation is a general increase in the prices of goods and services that reduces the purchasing power of money."}$json$::jsonb where id = '64f0d2d9-1559-4469-9234-75cb9a6dab79';
