update public.content_variants set body = $json${"type":"ordering","answer":["Record income","Divide expenses into categories","Set savings goals","End of month evaluation"],"options":["Set savings goals","Record income","End of month evaluation","Divide expenses into categories"],"question":"Sequence the steps to create a simple budget:","difficulty":"beginner","parameters":{},"explanation":"Record income, divide expenses, set savings goals, then evaluate."}$json$::jsonb where id = '65f19304-4b5e-4fe8-a1bf-41f827ab1683';
update public.content_variants set body = $json${"type":"true_false","answer":true,"question":"Compound interest makes money grow faster over time.","difficulty":"intermediate","explanation":"Interest is calculated on the balance that continues to increase, so growth is faster."}$json$::jsonb where id = '66a35cd7-db19-4bb2-a18c-f4e7b881ab8e';
update public.content_variants set body = $json${"type":"case_study","answer":"The first priority is basic protection and stopping the debt spiral.","caseText":"Ani, 19 years old, income IDR 2.5 million/month, no emergency fund, PayLater debt IDR 2 million.","followUp":{"answer":"Create a small emergency fund and cut out new purchases","options":["Create a small emergency fund and cut out new purchases","Direct investment in shares","Buy a new gadget for work","Apply for a new loan to pay off PayLater"],"question":"What is the most important first step?","explanation":"A small emergency fund prevents additional debt; stopping new purchases stops the debt spiral."},"question":"Read the following cases and choose the best sequence of steps.","difficulty":"advanced","explanation":"A financial plan starts from the foundation: emergency fund, debt, budget, protection, then investment."}$json$::jsonb where id = '689144f6-9f59-42bf-bcd5-fdb0ffa87f6b';
update public.content_variants set body = $json${"type":"true_false","answer":true,"question":"Bank savings are very low risk, so the interest is usually low.","difficulty":"intermediate","explanation":"Low risk is generally offset by low returns."}$json$::jsonb where id = '6a0ac6c3-d54a-4353-acf9-784cd1610ed2';
update public.content_variants set body = $json${"type":"fill_blank","answer":"debt","question":"Net worth is calculated from total assets minus total _____.","difficulty":"beginner","explanation":"Net worth = assets - debts. This shows how much treasure we really have."}$json$::jsonb where id = '6d8c020e-5b0b-4713-95c5-89dd53ddec9c';
